package server

const sessionTimeoutSettingsHTML = `<section class="wide" id="session-timeouts" data-settings-group="general"><h2>Automatic sign-out</h2><p>Each access type has its own inactivity and total sign-in limits. Every option signs out eventually.</p><p>Longer limits apply to new sign-ins. Shorter limits also apply to existing sessions, which sign out when either limit is reached.</p><h3>Private access</h3><p>Local network and WireGuard browser sessions.</p><form data-timeout-access="private" action="/settings/session-timeouts" method="post"><div class="profile-row session-timeouts"><label>After inactivity <select name="inactiveHours"><option value="0.25" {{if eq .SessionInactiveHours 0.25}}selected{{end}}>15 minutes (recommended)</option><option value="1" {{if eq .SessionInactiveHours 1.0}}selected{{end}}>1 hour</option><option value="8" {{if eq .SessionInactiveHours 8.0}}selected{{end}}>8 hours</option><option value="24" {{if eq .SessionInactiveHours 24.0}}selected{{end}}>1 day</option><option value="72" {{if eq .SessionInactiveHours 72.0}}selected{{end}}>3 days</option><option value="168" {{if eq .SessionInactiveHours 168.0}}selected{{end}}>7 days</option><option value="720" {{if eq .SessionInactiveHours 720.0}}selected{{end}}>30 days</option><option value="2160" {{if eq .SessionInactiveHours 2160.0}}selected{{end}}>90 days</option><option value="8760" {{if eq .SessionInactiveHours 8760.0}}selected{{end}}>1 year</option></select></label><label>Always after <select name="absoluteHours"><option value="4" {{if eq .SessionAbsoluteHours 4.0}}selected{{end}}>4 hours</option><option value="8" {{if eq .SessionAbsoluteHours 8.0}}selected{{end}}>8 hours (recommended)</option><option value="24" {{if eq .SessionAbsoluteHours 24.0}}selected{{end}}>1 day</option><option value="168" {{if eq .SessionAbsoluteHours 168.0}}selected{{end}}>7 days</option><option value="720" {{if eq .SessionAbsoluteHours 720.0}}selected{{end}}>30 days</option><option value="2160" {{if eq .SessionAbsoluteHours 2160.0}}selected{{end}}>90 days</option><option value="8760" {{if eq .SessionAbsoluteHours 8760.0}}selected{{end}}>1 year</option></select></label></div><button>Save private timeouts</button></form><h3>Public access</h3><p>Public-internet Viewer browser sessions. Other public clients use the absolute limit. Owner access remains private. Longer limits keep signed-in devices authorized for longer.</p>{{if not .PublicSessionTimeoutsConfigured}}<p>Until you save public timeouts, public browsers use the private inactivity limit and an absolute limit of at most 8 hours.</p>{{end}}<form data-timeout-access="public" action="/settings/public-session-timeouts" method="post"><div class="profile-row session-timeouts"><label>After inactivity <select name="inactiveHours"><option value="0.25" {{if eq .PublicSessionInactiveHours 0.25}}selected{{end}}>15 minutes (recommended)</option><option value="1" {{if eq .PublicSessionInactiveHours 1.0}}selected{{end}}>1 hour</option><option value="8" {{if eq .PublicSessionInactiveHours 8.0}}selected{{end}}>8 hours</option><option value="24" {{if eq .PublicSessionInactiveHours 24.0}}selected{{end}}>1 day</option><option value="72" {{if eq .PublicSessionInactiveHours 72.0}}selected{{end}}>3 days</option><option value="168" {{if eq .PublicSessionInactiveHours 168.0}}selected{{end}}>7 days</option><option value="720" {{if eq .PublicSessionInactiveHours 720.0}}selected{{end}}>30 days</option><option value="2160" {{if eq .PublicSessionInactiveHours 2160.0}}selected{{end}}>90 days</option><option value="8760" {{if eq .PublicSessionInactiveHours 8760.0}}selected{{end}}>1 year</option></select></label><label>Always after <select name="absoluteHours"><option value="4" {{if eq .PublicSessionAbsoluteHours 4.0}}selected{{end}}>4 hours</option><option value="8" {{if eq .PublicSessionAbsoluteHours 8.0}}selected{{end}}>8 hours (recommended)</option><option value="24" {{if eq .PublicSessionAbsoluteHours 24.0}}selected{{end}}>1 day</option><option value="168" {{if eq .PublicSessionAbsoluteHours 168.0}}selected{{end}}>7 days</option><option value="720" {{if eq .PublicSessionAbsoluteHours 720.0}}selected{{end}}>30 days</option><option value="2160" {{if eq .PublicSessionAbsoluteHours 2160.0}}selected{{end}}>90 days</option><option value="8760" {{if eq .PublicSessionAbsoluteHours 8760.0}}selected{{end}}>1 year</option></select></label></div><button>Save public timeouts</button></form></section>`
